package e.e.a;
import android.app.*;import android.content.*;import android.os.*;import android.widget.Toast;import java.io.*;
public final class CacheRetry {
 public static void confirm(Activity a,String id,String title){if(!id.matches("(?:sm|nm|so|ss)[0-9]+"))return;UiDialogs.show(UiDialogs.builder(PlaybackSession.dialogContext(a)).setTitle(UiStrings.translate("キャッシュを再取得")).setMessage(UiStrings.translate("保存済みの動画データを削除して再取得します。")+"\n"+title).setPositiveButton(UiStrings.translate("再取得"),(d,w)->start(a,id,title)).setNegativeButton(UiStrings.translate("キャンセル"),null).create());}
 private static void start(Activity a,String id,String title){new Thread(()->{try{if(Class.forName("com.sauzask.nicoid.NicoidDownloadCache").getField("v").getBoolean(null))throw new IOException("Cache acquisition is active");CacheControl110.await();String folder=CacheFolders.root(a)+"/nicoid/nicoid_cache/";File root=new CacheFile(folder);File[] files=root.listFiles();if(files==null)throw new IOException("Cache folder unavailable");for(File file:files)if(id.equals(CacheFolders.videoId(file.getName()))&&!file.getName().endsWith(".json")&&!file.getName().endsWith(".thm")&&!file.delete())throw new IOException("Unable to remove old media");CachePack.invalidate(new CacheFile(folder,id+".ncache"));new Handler(Looper.getMainLooper()).post(()->{if(!a.isFinishing())CacheFolders.startForegroundService(a,CachedPlayback.acquisitionIntent(a,id));});}catch(Exception e){new Handler(Looper.getMainLooper()).post(()->Toast.makeText(a,UiStrings.translate("キャッシュを再取得できませんでした。取得中の場合は完了後に再試行してください。"),Toast.LENGTH_LONG).show());}},"nicoid-cache-retry").start();}
}
